target.css:
:root {
  --ink: #193447;
  --muted: #6d7f87;
  --paper: #fffdf7;
  --line: #d6e0de;
  --navy: #1f5269;
  --mint: #d9eee5;
  --mint-strong: #4d917d;
  --amber: #e7ad42;
  --coral: #df7669;
  --blue: #91c5d5;
  --white: #ffffff;
}

.sort-board,
.sort-board * {
  box-sizing: border-box;
}

.sort-board {
  width: 500px;
  height: 278px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.board-header {
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  color: var(--white);
  background: var(--navy);
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.kicker {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--blue);
}

.title-block h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1;
  letter-spacing: -0.03em;
}

.shift-badge {
  padding: 6px 9px;
  border: 1px solid var(--blue);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  color: var(--white);
}

.board-body {
  height: 174px;
  display: grid;
  grid-template-columns: 1.18fr 0.82fr;
  gap: 10px;
  padding: 10px 12px;
}

.incoming,
.summary-panel {
  min-width: 0;
}

.summary-panel {
  padding-left: 10px;
  border-left: 1px solid var(--line);
}

.section-head {
  height: 25px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.section-head h2 {
  margin: 0;
  font-size: 13px;
  line-height: 1;
  letter-spacing: -0.01em;
}

.section-head span {
  font-size: 10px;
  font-weight: 700;
  color: var(--muted);
}

.material-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 3px 0 0;
  padding: 0;
  list-style: none;
}

.material-item {
  height: 37px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 7px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 9px;
}

.material-icon {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 7px;
  font-size: 16px;
  font-weight: 700;
  color: var(--navy);
  background: var(--mint);
}

.material-copy {
  min-width: 0;
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

.material-copy strong {
  overflow: hidden;
  font-size: 12px;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.material-copy small {
  font-size: 10px;
  line-height: 1.1;
  color: var(--muted);
}

.lane {
  padding: 4px 5px;
  border-radius: 5px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.lane-paper {
  color: var(--navy);
  background: var(--blue);
}

.lane-metal {
  color: var(--ink);
  background: var(--amber);
}

.lane-plastic {
  color: var(--white);
  background: var(--mint-strong);
}

.rate-display {
  height: 57px;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 7px;
  margin-top: 4px;
  border-radius: 10px;
  background: var(--mint);
}

.rate-display strong {
  font-size: 31px;
  line-height: 1;
  letter-spacing: -0.07em;
  color: var(--navy);
}

.rate-display span {
  font-size: 10px;
  font-weight: 700;
  color: var(--mint-strong);
}

.bin-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
}

.bin-grid li {
  height: 45px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-left: 7px;
  border-radius: 8px;
}

.bin-grid strong {
  font-size: 14px;
  line-height: 1;
}

.bin-grid span {
  margin-top: 3px;
  font-size: 9px;
  font-weight: 700;
}

.bin-paper {
  color: var(--navy);
  background: var(--blue);
}

.bin-metal {
  color: var(--ink);
  background: var(--amber);
}

.bin-plastic {
  color: var(--white);
  background: var(--coral);
}

.board-footer {
  height: 52px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  border-top: 1px solid var(--line);
  background: var(--white);
}

.run-note {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  color: var(--ink);
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--mint-strong);
}

.legend {
  display: flex;
  gap: 7px;
  margin-left: auto;
  font-size: 9px;
  color: var(--muted);
}

.hold-button {
  padding: 7px 10px;
  border: 1px solid var(--coral);
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
  color: var(--coral);
  background: var(--paper);
}

